                    var dattrs = [
                        { type: "power", num: attrs.level2AddPower }, { type: "hp", num: attrs.level3AddHp }, { type: "critical", num: attrs.level4AddCritical },
                        { type: "dodge", num: attrs.level5AddDodge }
                    ];
