class LevelLogicAwardInherited extends LevelLogic {
    constructor(ps) {
        super("LevelLogicAwardInherited");
        this.relicTypes = [];
        this.leftCoinsNum = 0;
        this.allCoinsNum = 0;
        this.relicTypes = ps.relicTypes;
        this.leftCoinsNum = ps.leftCoinsNum;
        this.allCoinsNum = ps.allCoinsNum;
        this.relicsLv = ps.relicsLv;
        this.addAI("onLevelInitElems", (ps) => {
            Utils.assert(this.relicTypes.length == 2, "not enough relicTypes for award");
            // 6个宝箱,分别装两个技能,金币,3种药水
            var tb1 = this.level.createElem("TreasureBox");
            var relic1 = this.level.createElem(this.relicTypes[0]);
            if (this.relicsLv[relic1.type] > 0)
                relic1.setReinfoceLv(this.relicsLv[relic1.type]);
            tb1.addDropItem(relic1);
            var tb2 = this.level.createElem("TreasureBox");
            var relic2 = this.level.createElem(this.relicTypes[1]);
            if (this.relicsLv[relic2.type])
                relic2.setReinfoceLv(this.relicsLv[relic2.type]);
            tb2.addDropItem(relic2);
            var tb3 = this.level.createElem("TreasureBox");
            tb3.addDropItem(this.level.createElem("Coins", { "cnt": this.allCoinsNum }));
            var tb4 = this.level.createElem("TreasureBox");
            tb4.addDropItem(this.level.createElem("RayGun"));
            var tb5 = this.level.createElem("TreasureBox");
            tb5.addDropItem(this.level.createElem("IceGun"));
            var tb6 = this.level.createElem("TreasureBox");
            var occPropType = GCfg.getOccupationCfg(this.level.bt.player.occupation)["occPropType"];
            tb6.addDropItem(this.level.createElem(occPropType));
            // 金币
            var coins = this.level.createElem("Coins", { "cnt": this.leftCoinsNum });
            var awards = [tb1, tb2, tb3, tb4, tb5, tb6, coins];
            // 7把钥匙
            for (var i = 0; i < 7; i++) {
                var key = this.level.createElem("Key");
                awards.push(key);
            }
            for (var award of awards)
                ps.elems.push(award);
        }, true);
    }
}
class LevelLogicBoss extends LevelLogic {
    constructor(bossType) {
        super("LevelLogicBoss");
        this.valid = true;
        this.bossType = bossType;
        // 创建关卡时添加boss
        this.addAI("onLevelInitElems", (ps) => {
            var e = this.level.createElem(this.bossType);
            ps.elems.push(e);
        }, true);
        // boss被消灭后添加豪华宝箱
        this.addAI("onElemChanged", async (ps) => {
            if (ps.subType != "dead" || !this.valid)
                return;
            var bt = this.level.bt;
            var ms = this.level.map.findAllElems((e) => e instanceof Monster && e.isHazard() && e.type != "PlaceHolder");
            if (ms.length == 0) {
                this.valid = false;
                var g = BattleUtils.findRandomEmptyGrid(this.level.bt, false);
                if (g) {
                    await bt.fireEvent("onGetMarkAllAward", { btType: "boss" });
                    var luxuryChest = this.level.createElem("LuxuryChest");
                    await bt.implAddElemAt(luxuryChest, g.pos.x, g.pos.y);
                    await bt.triggerLogicPoint("onGetMarkAllAward", { btType: "boss" });
                }
            }
        });
    }
}
class LevelLogicChangeMonster extends LevelLogic {
    constructor(changeTypes, num, prior = undefined, extraInvalidTypes = []) {
        super("LevelLogicChangeMonster");
        this.changeTypes = changeTypes;
        this.invalidTypes = [...changeTypes, ...extraInvalidTypes];
        this.num = num;
        this.addAI("beforeLevelInitedChangeMonster", async (ps) => {
            var bt = this.level.bt;
            var hasKey = (e) => Utils.filter(e.dropItems, (d) => d.type == "Key").length != 0;
            // 筛选不属于要改变的种类之一并且不含金币以外掉落的敌对怪进行替换
            var tarms = BattleUtils.findRandomElems(bt, this.num, (e) => {
                if (!(e instanceof Monster))
                    return false;
                return e.isHazard() && !e.isBoss && !e.isElite && !Utils.contains(this.invalidTypes, e.type) && e.type != "PlaceHolder";
            });
            // 部分变化属于优先的 prior是形如{type1:num1, type2:num2}的表
            if (prior) {
                for (var priorType in prior)
                    for (var i = 0; i < prior[priorType]; i++) {
                        if (tarms.length > 0) {
                            var target = tarms.shift();
                            var pos = target.pos;
                            var m = this.level.createElem(priorType);
                            if (hasKey(target)) {
                                var hasKeys = Utils.filter(target.dropItems, (d) => d.type == "Key");
                                for (var key of hasKeys)
                                    m.addDropItem(key);
                            }
                            await bt.implRemoveElemAt(pos.x, pos.y);
                            await bt.implAddElemAt(m, pos.x, pos.y);
                        }
                    }
            }
            for (var i = 0; i < tarms.length; i++) {
                var type = changeTypes[bt.srand.nextInt(0, changeTypes.length)];
                var m = this.level.createElem(type);
                var pos = tarms[i].pos;
                if (hasKey(tarms[i])) {
                    var hasKeys = Utils.filter(tarms[i].dropItems, (d) => d.type == "Key");
                    for (var key of hasKeys)
                        m.addDropItem(key);
                }
                await bt.implRemoveElemAt(pos.x, pos.y);
                await bt.implAddElemAt(m, pos.x, pos.y);
            }
        });
    }
}
