class LevelLogicMarkAllAward extends LevelLogic {
    constructor(rdp) {
        super("LevelLogicMarkAllAward");
        this.valid = true;
        this.rdp = rdp;
        this.addAI("afterGridUncovered", async (ps) => {
            if (!this.valid)
                return;
            var bt = this.level.bt;
            var gs = this.level.map.findAllGrid((x, y, g) => {
                if (!g.isCovered())
                    return false;
                var e = g.getElem();
                return !e || !(e instanceof Monster) || !e.isHazard();
            });
            if (gs.length != 0)
                return;
            var boxGrid = BattleUtils.findRandomEmptyGrid(bt);
            if (boxGrid) {
                // 钥匙优先掉落在怪物身上
                var keyGrid = this.level.map.findFirstGrid((x, y, g) => {
                    if (g == boxGrid)
                        return false;
                    var e = g.getElem();
                    if (e && e instanceof Monster && e.isHazard() && !e.isBig() && e.type != "PlaceHolder" && !e.attrs.cannotTake)
                        return Utils.indexOf(e.dropItems, (dp) => dp.type != "Coins") == -1;
                });
                // 没有目标怪物则掉落在空地上
                if (!keyGrid)
                    keyGrid = BattleUtils.findRandomGrids(bt, (g) => !g.isCovered() && !g.getElem() && g != boxGrid, 1)[0];
                // 分配好宝箱和钥匙的目标位置都才一起掉落出来
                if (keyGrid) {
                    this.valid = false;
                    await bt.fireEvent("onGetMarkAllAward", { btType: "normal" });
                    var box = this.level.createElem("TreasureBox", { rdp: this.rdp });
                    await bt.implAddElemAt(box, boxGrid.pos.x, boxGrid.pos.y);
                    var key = this.level.createElem("Key");
                    var e = keyGrid.getElem();
                    if (!e) {
                        Utils.assert(!keyGrid.isCovered(), "only uncovered grid without monster is valid");
                        await bt.implAddElemAt(key, keyGrid.pos.x, keyGrid.pos.y);
                    }
                    else {
                        Utils.assert(e instanceof Monster, "only monster can take the key: " + e.type + " at " + keyGrid.pos.x + ", " + keyGrid.pos.y);
                        e.addDropItem(key);
                        await bt.fireEvent("onElemImgFlying", { e: key, fromPos: boxGrid.pos, toPos: keyGrid.pos });
                    }
                    await bt.triggerLogicPoint("onGetMarkAllAward", { btType: "normal" });
                }
            }
        });
    }
}
class LevelLogicRandomEgg extends LevelLogic {
    constructor(rdp) {
        super("LevelLogicRandomEgg");
        this.valid = true;
        this.rdp = rdp;
        this.addAI("onElemChanged", async (ps) => {
            if (ps.subType != "dead" || !this.valid)
                return;
            var map = this.level.map;
            var bt = this.level.bt;
            var randomEggZombies = map.findAllElems((e) => e.type == "RandomEggZombie");
            if (randomEggZombies.length == 0) {
                // 判断是出现监狱还是道具
                // 概率为10%
                var rate = this.level.bt.srand.next100();
                // 几率随机到并且有可解锁职业才出密室
                if (rate < 100 && Utils.getLockedOccupations().length > 0) {
                    var pg = BattleUtils.findRandomEmptyGrid(this.level.bt, false);
                    if (pg) {
                        this.valid = false;
                        var prison = this.level.createElem("Prison");
                        await bt.fireEvent("onGetMarkAllAward", { btType: "randomEgg" });
                        await this.level.bt.implAddElemAt(prison, pg.pos.x, pg.pos.y);
                    }
                }
                // 其他情况奖励道具
                else {
                    var gs = map.findAllGrid((x, y, g) => {
                        if (!g.isCovered())
                            return false;
                        var e = g.getElem();
                        return !e || !(e instanceof Monster) || !e.isHazard();
                    });
                    if (gs.length != 0)
                        return;
                    var boxGrid = BattleUtils.findRandomEmptyGrid(bt);
                    if (boxGrid) {
                        // 钥匙优先掉落在怪物身上
                        var keyGrid = map.findFirstGrid((x, y, g) => {
                            if (g == boxGrid)
                                return false;
                            var e = g.getElem();
                            if (e && e instanceof Monster && e.isHazard() && !e.isBig() && e.type != "PlaceHolder" && !e.attrs.cannotTake)
                                return Utils.indexOf(e.dropItems, (dp) => dp.type != "Coins") == -1;
                        });
                        // 没有目标怪物则掉落在空地上
                        if (!keyGrid)
                            keyGrid = BattleUtils.findRandomGrids(bt, (g) => !g.isCovered() && !g.getElem() && g != boxGrid, 1)[0];
                        // 分配好宝箱和钥匙的目标位置都才一起掉落出来
                        if (keyGrid) {
                            this.valid = false;
                            await bt.fireEvent("onGetMarkAllAward", { btType: "randomEgg" });
                            var box = this.level.createElem("TreasureBox", { rdp: this.rdp });
                            await bt.implAddElemAt(box, boxGrid.pos.x, boxGrid.pos.y);
                            var key = this.level.createElem("Key");
                            var e = keyGrid.getElem();
                            if (!e) {
                                Utils.assert(!keyGrid.isCovered(), "only uncovered grid without monster is valid");
                                await bt.implAddElemAt(key, keyGrid.pos.x, keyGrid.pos.y);
                            }
                            else {
                                Utils.assert(e instanceof Monster, "only monster can take the key: " + e.type + " at " + keyGrid.pos.x + ", " + keyGrid.pos.y);
                                e.addDropItem(key);
                                await bt.fireEvent("onElemImgFlying", { e: key, fromPos: boxGrid.pos, toPos: keyGrid.pos });
                            }
                            await bt.triggerLogicPoint("onGetMarkAllAward", { btType: "randomEgg" });
                        }
                    }
                }
            }
        });
    }
}
// 冒险者的尸体事件专用逻辑
class LevelLogicSearchBody extends LevelLogic {
    constructor(rdps) {
        super("LevelLogicSearchBody");
        this.rdps = rdps;
        this.addAI("beforeLevelInited", async (ps) => {
            var bt = this.level.bt;
            for (var i = 0; i < rdps.length; i++) {
                // 约定:传入的不是数字则为掉落组,是数字则为钱的数量
                if (isNaN(rdps[i]))
                    var box = this.level.createElem("TreasureBox", { rdp: rdps[i] });
                else {
                    var box = this.level.createElem("TreasureBox");
                    var coins = this.level.createElem("Coins", { cnt: rdps[i] });
                    box.addDropItem(coins);
                }
                var key = this.level.createElem("Key");
                var g = BattleUtils.findRandomGrids(bt, (g) => !g.getElem() && !g.isCovered(), 1)[0];
                if (g) {
                    await bt.implAddElemAt(box, g.pos.x, g.pos.y);
                    this.level.keys.push(key);
                }
            }
        });
    }
}
class LevelLogicTakeKey extends LevelLogic {
    constructor() {
        super("LevelLogicTakeKey");
        this.addAI("beforeLevelInitedTakeKey", async (ps) => {
            var bt = this.level.bt;
            var keys = this.level.keys;
            var index = bt.btType.indexOf("_");
            index = index < 0 ? bt.btType.length : index;
            var btType = bt.btType.substring(0, index);
            var seniorTypes = GCfg.getBattleTypes("senior");
            var bossTypes = GCfg.getBattleTypes("boss");
            // 精英关卡,如果是双精英怪,每个精英怪取走2把,单精英则取走4把
            if (Utils.indexOf(seniorTypes, (t) => t == btType) > -1) {
                var elites = bt.level.map.findAllElems((e) => e instanceof Monster && e.isElite);
                // 多个精英怪
                if (elites.length > 1) {
                    for (var elite of elites) {
                        for (var i = 0; i < 2; i++) {
                            var key = keys[bt.srand.nextInt(0, keys.length)];
                            if (key) {
                                await bt.implMonsterAddDropItem(elite, key);
                                keys = Utils.remove(keys, key);
                            }
                        }
                    }
                }
                // 单个精英怪
                else if (elites.length == 1) {
                    var elite = elites[0];
                    for (var i = 0; i < 4; i++) {
                        var key = keys[bt.srand.nextInt(0, keys.length)];
                        if (key) {
                            await bt.implMonsterAddDropItem(elite, key);
                            keys = Utils.remove(keys, key);
                        }
                    }
                }
                // 多余的钥匙分配给普通怪
                if (keys.length > 0) {
                    var takeByNormal = bt.srand.nextInt(keys.length - 1, keys.length + 1);
                    if (takeByNormal > 0)
                        keys = await this.normalMonsterTakeKey(bt, keys, takeByNormal);
                    if (keys.length > 0) {
                        var gs = BattleUtils.findRandomGrids(bt, (g) => !g.getElem(), keys.length);
                        Utils.assert(gs.length == keys.length, "not enough empty grids");
                        for (var i = 0; i < gs.length; i++)
                            await bt.implAddElemAt(keys[i], gs[i].pos.x, gs[i].pos.y);
                    }
                }
            }
            // boss关卡,4把钥匙分配到boss身上
            else if (Utils.indexOf(bossTypes, (t) => t == btType) > -1) {
                var boss = bt.level.map.findAllElems((e) => e instanceof Monster && e.isBoss)[0];
                for (var i = 0; i < 4; i++) {
                    var key = keys[bt.srand.nextInt(0, keys.length)];
                    await bt.implMonsterAddDropItem(boss, key);
                    keys = Utils.remove(keys, key);
                }
                // 多余的钥匙分配给普通怪
                keys = await this.normalMonsterTakeKey(bt, keys, keys.length);
                if (keys.length > 0) {
                    var gs = BattleUtils.findRandomGrids(bt, (g) => !g.getElem(), keys.length);
                    Utils.assert(gs.length == keys.length, "not enough empty grids");
                    for (var i = 0; i < gs.length; i++)
                        await bt.implAddElemAt(keys[i], gs[i].pos.x, gs[i].pos.y);
                }
            }
            // 普通关卡将钥匙分配至普通怪物身上,地上留0~1把钥匙
            else {
                var takeNum = bt.srand.nextInt(keys.length - 1, keys.length + 1);
                keys = await this.normalMonsterTakeKey(bt, keys, takeNum);
                if (keys.length > 0) {
                    var gs = BattleUtils.findRandomGrids(bt, (g) => !g.getElem(), keys.length);
                    Utils.assert(gs.length == keys.length, "not enough empty grids");
                    for (var i = 0; i < gs.length; i++)
                        await bt.implAddElemAt(keys[i], gs[i].pos.x, gs[i].pos.y);
                }
            }
        });
    }
    // 将一定数量的钥匙分配给普通怪物
    async normalMonsterTakeKey(bt, keys, takeNum) {
        Utils.assert(keys.length >= takeNum && takeNum > 0, "keys's amount or takeNum error.");
        var ms = BattleUtils.findRandomElems(bt, takeNum, (e) => e instanceof Monster && !e.isBoss && !e.isElite && e.isHazard() && !e.attrs.cannotTake);
        for (var m of ms) {
            var key = keys[bt.srand.nextInt(0, keys.length)];
            keys = Utils.remove(keys, key);
            await bt.implMonsterAddDropItem(m, key);
        }
        return keys;
    }
}
// 地图上每一个格子的状态
var GridStatus;
(function (GridStatus) {
    GridStatus[GridStatus["Covered"] = 0] = "Covered";
    GridStatus[GridStatus["Uncovered"] = 1] = "Uncovered";
    GridStatus[GridStatus["Marked"] = 2] = "Marked";
    GridStatus[GridStatus["Blocked"] = 3] = "Blocked";
})(GridStatus || (GridStatus = {}));
// 表示一个地图格
class Grid {
    constructor() {
        // 表示地图块的坐标
        this.pos = { x: 0, y: 0 };
        // 地图格子默认是覆盖的状态
        this.status = GridStatus.Covered;
    }
    // 广义上的覆盖状态
    isCovered() { return this.status != GridStatus.Uncovered; }
    // 被标记
    isMarked() { return this.status == GridStatus.Marked; }
    // 可以被揭开
    isUncoverable() { return this.map.isUncoverable(this.pos.x, this.pos.y); }
    // 已经被揭开或者被标记
    isUncoveredOrMarked() { return this.status == GridStatus.Uncovered || this.status == GridStatus.Marked; }
    // 获取其上的元素
    getElem() { return this.map.getElemAt(this.pos.x, this.pos.y); }
}
// 实时的游戏地图，用于存放所有地图格和元素
class Map {
    constructor() {
        this.size = { w: 0, h: 0 }; // 地图尺寸
        var w = GCfg.mapsize.w;
        var h = GCfg.mapsize.h;
        this.size = { w: w, h: h };
        this.grids = [];
        this.elems = [];
        for (var i = 0; i < this.size.w; i++) {
            var x = i;
            this.grids[x] = [];
            this.elems[x] = [];
            for (var j = 0; j < this.size.h; j++) {
                var y = j;
                // 创建地块
                var g = new Grid();
                g.pos = { x: x, y: y };
                g.map = this;
                g.status = GridStatus.Uncovered;
                this.grids[x].push(g);
                // 地图创建时，地块上没有元素，但是要把位置先占住
                this.elems[x].push(undefined);
            }
        }
    }
    // 检查边界，越界则报异常
    assertBound(x, y) {
        if (x < 0 || x >= this.size.w || y < 0 || y >= this.size.h)
            throw new Error("index out of bounds");
    }
    // 获取指定位置的元素
    getElemAt(x, y) {
        this.assertBound(x, y);
        return this.elems[x][y];
    }
    // 获取指定位置的地块
    getGridAt(x, y) {
        this.assertBound(x, y);
        return this.grids[x][y];
    }
    // 计算指定目标位置的 8 邻位置上，隐藏的有害元素个数，不计算目标位置自身
    getCoveredHazardNum(cx, cy) {
        var num = 0;
        this.travel8Neighbours(cx, cy, (x, y, g) => {
            var e = g.getElem();
            if (e && e.isHazard() && e.getGrid().isCovered()) {
                if (e.hideHazardNum())
                    num = -1;
                else
                    num++;
            }
            return num < 0;
        });
        return num;
    }
    // 对指定位置的 8 邻做过滤计算，不包括目标自身, f 是遍历函数，形如 function(x, y, g:Grid):boolean，
    // 返回值表示是否要中断遍历
    travel8Neighbours(x, y, f) {
        var breakLoop = false;
        for (var i = x - 1; i <= x + 1 && !breakLoop; i++) {
            for (var j = y - 1; j <= y + 1 && !breakLoop; j++) {
                if (i < 0 || i >= this.size.w || j < 0 || j >= this.size.h)
                    continue; // 越界忽略
                else if (i == x && y == j) // 目标格子不计算在内，只计算八邻位置
                    continue;
                breakLoop = f(i, j, this.grids[i][j]);
            }
        }
    }
    // 对指定位置的 4 邻做过滤计算，不包括目标自身, f 是遍历函数，形如 function(x, y, g:Grid):boolean，
    // 返回值表示是否要中断遍历
    travel4Neighbours(x, y, f) {
        var breakLoop = false;
        var neighbours = [{ x: x - 1, y: y }, { x: x + 1, y: y }, { x: x, y: y - 1 }, { x: x, y: y + 1 }];
        for (var i = 0; i < neighbours.length; i++) {
            var n = neighbours[i];
            if (n.x < 0 || n.x >= this.size.w || n.y < 0 || n.y >= this.size.h)
                continue; // 越界忽略
            breakLoop = f(n.x, n.y, this.grids[n.x][n.y]);
        }
    }
    // 指定位置是否可用（不考虑特殊可用逻辑，比如全图可用等），如果有显形的有害怪物在附近，则不可用。
    // 不可用影响空地探索，也影响物品使用和生效
    isGenerallyValid(x, y) {
        var g = this.getGridAt(x, y);
        var e = this.getElemAt(x, y);
        if (!g.isCovered()) { // 揭开的怪或空地始终可用
            if (!e || e instanceof Monster)
                return true;
        }
        else if (g.status == GridStatus.Marked && e instanceof Monster)
            return true; // 被标记的怪也可用
        var valid = true;
        this.travel8Neighbours(x, y, (x, y, g) => {
            var e = g.isCovered() ? undefined : g.getElem();
            valid = !e || !e.isHazard();
            return !valid;
        });
        return valid;
    }
    // 是否可以揭开（未揭开状态，四邻至少一个揭开，且没有怪物相邻）
    isUncoverable(x, y) {
        var g = this.grids[x][y];
        if (g.status == GridStatus.Uncovered || g.status == GridStatus.Blocked)
            return false;
        var uncoverable = false; // 检查 4 邻是否有揭开，且不阻挡
        this.travel4Neighbours(x, y, (x, y, g) => {
            var e = g.getElem();
            if (!g.isCovered() && (!e || !e.isBarrier()))
                uncoverable = true;
            return uncoverable;
        });
        // 检查 8 邻是否有怪
        if (uncoverable)
            uncoverable = this.isGenerallyValid(x, y);
        return uncoverable;
    }
    // 是否可行走
    isWalkable(x, y) {
        if (x < 0 || x >= this.size.w || y < 0 || y >= this.size.h)
            return false;
        if (this.elems[x][y] || this.grids[x][y].isCovered())
            return false;
        return true;
    }
    // 纵向优先依次序遍历地图中的所有格子, f 是遍历函数，形如 function(x:number, y:nubmer):boolean，
    // 返回值表示是否要继续遍历
    travelAll(f) {
        var breakLoop = false;
        for (var i = 0; i < this.size.w && !breakLoop; i++) {
            for (var j = 0; j < this.size.h && !breakLoop; j++) {
                breakLoop = f(i, j);
            }
        }
    }
    // 在指定位置添加一个元素，如果位置已经被占用，则会报错
    addElemAt(e, x, y) {
        this.assertBound(x, y);
        if (this.elems[x][y]) {
            var str = "it's not empty at [" + x + "][" + y + "] for " + e.type + " over " + this.elems[x][y].type;
            throw new Error(str);
        }
        e.pos = { x: x, y: y };
        this.elems[x][y] = e;
        if (e.isBig()) {
            this.assertBound(x + e.attrs.size.w - 1, y + e.attrs.size.h - 1);
            var hds = e["placeHolders"]();
            var index = 0;
            for (var i = 0; i < e.attrs.size.w; i++) {
                for (var j = 0; j < e.attrs.size.h; j++) {
                    if (i == 0 && j == 0)
                        continue;
                    this.addElemAt(hds[index], x + i, y + j);
                    index++;
                }
            }
        }
    }
    // 移除一个指定位置的元素
    removeElemAt(x, y) {
        this.assertBound(x, y);
        var e = this.getElemAt(x, y);
        if (!e)
            throw new Error("no element at [" + x + "][" + y + "]");
        this.elems[x][y] = undefined;
        if (e.isBig()) {
            var hds = e["placeHolders"]();
            for (var hd of hds)
                this.removeElemAt(hd.pos.x, hd.pos.y);
        }
        return e;
    }
    // 交换两个元素位置
    switchElems(x1, y1, x2, y2) {
        this.assertBound(x1, y1);
        this.assertBound(x2, y2);
        var e1 = this.elems[x1][y1];
        var e2 = this.elems[x2][y2];
        this.elems[x1][y1] = e2;
        this.elems[x2][y2] = e1;
        if (this.elems[x1][y1])
            this.elems[x1][y1].pos = { x: x1, y: y1 };
        if (this.elems[x2][y2])
            this.elems[x2][y2].pos = { x: x2, y: y2 };
    }
    // 寻找满足条件的第一个 Grid
    findFirstGrid(f) {
        var g;
        this.travelAll((x, y) => {
            if (f(x, y, this.grids[x][y])) {
                g = this.grids[x][y];
                return true; //　找到第一个就停止遍历
            }
        });
        return g;
    }
    // 寻找满足条件的所有 Grid
    findAllGrid(f) {
        var grids = [];
        this.travelAll((x, y) => {
            if (f(x, y, this.grids[x][y])) {
                grids.push(this.grids[x][y]);
            }
        });
        return grids;
    }
    // 寻找满足条件的第一个 Elem
    findFirstElem(f) {
        var e;
        this.travelAll((x, y) => {
            var elem = this.elems[x][y];
            if (elem && f(elem)) {
                e = elem;
                return true; //　找到第一个就停止遍历
            }
        });
        return e;
    }
    // 寻找满足条件的第一个揭开了的 Elem
    findFirstUncoveredElem(f) {
        return this.findFirstElem((e) => e && !this.grids[e.pos.x][e.pos.y].isCovered() && f(e));
    }
    // 寻找所有满足条件的 Elem, f 是一个函数表示过滤条件，形如 function(e:elem):boolean
    findAllElems(f = undefined) {
        var es = [];
        this.travelAll((x, y) => {
            var e = this.elems[x][y];
            if (e && (!f || f(e)))
                es.push(e);
        });
        return es;
    }
    // 迭代每一个元素
    foreachElem(f, condition = undefined) {
        var es = [];
        Utils.NDimentionArrayForeach(this.elems, (e) => {
            if (e && (!condition || condition(e)))
                es.push(e);
        });
        for (var e of es) {
            if (f(e))
                break;
        }
    }
    // 迭代每一个活动元素, f 是一个形如 funciton(e:Elem):boolean 的函数，返回值表示是否要中断迭代
    foreachUncoveredElems(f) {
        this.foreachElem(f, (e) => !e.getGrid().isCovered());
    }
    // 确保寻路器准备继续
    makeSurePathFinderPrepared() {
        if (!this.pathGraph)
            this.preparePathFinder();
    }
    // 准备寻路器
    preparePathFinder() {
        Utils.assert(!this.pathGraph, "path graph is already prepared");
        var wf = (x, y) => {
            return (x == this.startPos.x && y == this.startPos.y)
                || (x == this.endPos.x && y == this.endPos.y)
                || this.isWalkable(x, y);
        };
        this.pathGraph = new astar.Graph(this.size.w, this.size.h, wf);
        return this.pathGraph != undefined;
    }
    // 执行寻路操作
    findPath(start, end, options) {
        Utils.assert(!!this.pathGraph, "path graph is not prepared yet");
        Utils.assert(Utils.isInArea(start, { x: 0, y: 0 }, this.size) && Utils.isInArea(end, { x: 0, y: 0 }, this.size), "start & end position should be in map area: " + start.x + ", " + start.y + " - " + end.x + ", " + end.y);
        this.startPos = start;
        this.endPos = end;
        var path = this.pathGraph.search(start.x, start.y, end.x, end.y, true);
        this.startPos = undefined;
        this.endPos = undefined;
        return path;
    }
}
// 用于计算怪物的 mark 逻辑
class MonsterMarker {
    // 从指定位置开始计算，看是否有怪物群应该被标记，
    // 被标记的条件是：
    // 1、包含指定位置的，一片互相连接且未解开的块，且和其它未揭开的块孤立
    // 2、这一片孤立的未揭开的块里面，全部是怪物，没有空地或者其它道具
    // 返回值表示要被标记的坐标序列，格式为 [[x1,y1], [x2,y2], ...]，无结果则返回 []
    static CalcMonsterMarkSignAt(map, x, y) {
        var forCheck = [[x, y]];
        var markPos = [];
        while (forCheck.length > 0) {
            var pos = forCheck.shift();
            var cx = pos[0];
            var cy = pos[1];
            var g = map.getGridAt(cx, cy);
            if (!g.isCovered()) // 被揭开了的不管
                continue;
            else {
                var e = map.getElemAt(cx, cy);
                if (!e || !e.isHazard()) // 如果有未揭开的非怪物，则直接返回结果
                    return [];
            }
            // 剩下的情况，应该就是未揭开的怪物了
            Utils.assert(g.isCovered() && e && e.isHazard(), "should be covered hazared element here!");
            // 这个块本自身入标记组，并开始检查其周围的相邻块
            markPos.push([cx, cy]);
            map.travel8Neighbours(cx, cy, (px, py, g) => {
                if (Utils.indexOf(markPos, (pt) => px == pt[0] && py == pt[1]) < 0
                    && Utils.indexOf(forCheck, (pt) => px == pt[0] && py == pt[1]) < 0) {
                    forCheck.push([px, py]);
                }
            });
        }
        return markPos;
    }
}
