    // 直线飞向目标位置并消失
    static async flyAndFadeoutArr(objArr, toPos, time, toScale, toAlpha, toRotation, mode) {
        var aniArr = [];
        var revArr = [];
        objArr.forEach((obj, i) => {
            revArr.push(AniUtils.reserveObjTrans(obj, toPos));
            aniArr.push(AniUtils.aniFact.createAniByCfg({
                type: "tr", tx: toPos.x, ty: toPos.y, ta: toAlpha, tr: toRotation, tsx: toScale, tsy: toScale,
                time: time, obj: obj, mode: mode
            }));
        });
        await AniUtils.aniFact.createAni("gp", { subAniArr: aniArr });
        revArr.forEach((rev, _) => {
            rev();
        });
        objArr.forEach((obj, _) => {
            obj.alpha = 0;
        });
    }
    static async flyAndFadeout(obj, toPos, time, toScale, toAlpha, toRotation, mode) {
        await AniUtils.flyAndFadeoutArr([obj], toPos, time, toScale, toAlpha, toRotation, mode);
    }
    static ani2global(obj) {
        var p1 = obj.localToGlobal();
        return AniUtils.ac.globalToLocal(p1.x, p1.y);
    }
    // 所有元素随机移动并不等待动画
    static LoopMoveAll(gs, mapview) {
        var revArr = [];
        var speed = 1;
        gs.forEach((g, _) => {
            var fromPos = AniUtils.ani2global(mapview.getGridViewAt(g["gx"], g["gy"]));
            var toPos1 = AniUtils.ani2global(mapview.getGridViewAt(g["tgx1"], g["tgy1"]));
            var toPos2 = AniUtils.ani2global(mapview.getGridViewAt(g["tgx2"], g["tgy2"]));
            var toPos3 = AniUtils.ani2global(mapview.getGridViewAt(g["tgx3"], g["tgy3"]));
            var parent = g.parent;
            AniUtils.ac.addChild(g);
            revArr.push(() => {
                egret.Tween.removeTweens(g);
                parent.addChild(g);
                g.x = g.y = 0;
            });
            var delay1 = g["delay1"];
            var delay2 = g["delay2"];
            var delay3 = g["delay3"];
            var delay4 = g["delay4"];
            var t1 = Utils.getDist(fromPos, toPos1) / speed;
            var t2 = Utils.getDist(toPos1, toPos2) / speed;
            var t3 = Utils.getDist(toPos2, toPos3) / speed;
            var t4 = Utils.getDist(toPos3, fromPos) / speed;
            egret.Tween.get(g, { loop: true }).to({ x: fromPos.x, y: fromPos.y }, 0)
                .to({ x: toPos1.x, y: toPos1.y }, t1, egret.Ease.circOut).to({}, delay1)
                .to({ x: toPos2.x, y: toPos2.y }, t2, egret.Ease.circOut).to({}, delay2)
                .to({ x: toPos3.x, y: toPos3.y }, t3, egret.Ease.circOut).to({}, delay3)
                .to({ x: fromPos.x, y: fromPos.y }, t4, egret.Ease.circOut).to({}, delay4);
        });
        return revArr;
    }
    // 开场盖住所有格子
    static async coverAll(mapView, actualMapRange) {
        // 牌背随机从四面八方飞过来盖住
        var eachTime = 1000;
        var mapsize = GCfg.mapsize;
        var gbgs = [];
        for (var x = 0; x < mapsize.w; x++) {
            for (var y = 0; y < mapsize.h; y++) {
                if (x <= actualMapRange.maxX && x >= actualMapRange.minX && y <= actualMapRange.maxY && y >= actualMapRange.minY) {
                    var bg = ViewUtils.createBitmapByName("covered_png");
                    bg["rn"] = Math.abs(x - mapsize.w) + y;
                    bg["fgx"] = mapsize.w - 1;
                    bg["fgy"] = 0;
                    bg["gx"] = x;
                    bg["gy"] = y;
                    AniUtils.ac.addChild(bg);
                    gbgs.push(bg);
                }
            }
        }
        // 排序
        gbgs.sort((g1, g2) => {
            var x1 = g1["rn"];
            var x2 = g2["rn"];
            if (x1 < x2)
                return 1;
            else if (x1 > x2)
                return -1;
            else
                return 0;
        });
        // 构建单个动画
        var aniArr = [];
        gbgs.forEach((g, i) => {
            var delay = i * eachTime / 30;
            var fromPos = mapView.logicPos2ShowPos(g["fgx"], g["fgy"]);
            fromPos = mapView.localToGlobal(fromPos.x, fromPos.y);
            fromPos = AniUtils.ac.globalToLocal(fromPos.x, fromPos.y);
            g.x = fromPos.x + g.width;
            g.y = fromPos.y - g.height;
            g.alpha = 0;
            var toPos = mapView.logicPos2ShowPos(g["gx"], g["gy"]);
            toPos = mapView.localToGlobal(toPos.x, toPos.y);
            toPos = AniUtils.ac.globalToLocal(toPos.x, toPos.y);
            var ani = this.aniFact.createAniByCfg({ type: "seq", obj: g, arr: [
                    { type: "delay", time: delay },
                    { type: "tr", tx: toPos.x, ty: toPos.y, ta: 1, time: eachTime * Math.sqrt(bg["rn"]) / 10 }
                ] });
            aniArr.push(ani);
        });
        // 把所有动画组合起来
        var ani = this.aniFact.createAni("gp", { subAniArr: aniArr });
        await ani;
        await AniUtils.delay(1000);
        gbgs.forEach((g, _) => {
            AniUtils.ac.removeChild(g);
        });
    }
    // 等待点击
    static async wait4click() {
        await AniUtils.wait4clickImpl();
    }
